#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    string s;
    while (cin >> s) {
        vector<string> words;
        string word;

        for (size_t i = 0; i < s.size();) {
            if (i + 2 < s.size() && s.substr(i, 3) == "WUB") {
                if (!word.empty()) {
                    words.push_back(word);
                    word.clear();
                }
                i += 3;
            } else {
                word += s[i++];
            }
        }

        if (!word.empty()) words.push_back(word);

        for (size_t i = 0; i < words.size(); ++i) {
            if (i) cout << ' ';
            cout << words[i];
        }
        cout << '\n';
    }

    return 0;
}

